"""Update the feature inventory for version 6. Usage: fill_v6_inventory.py in.md out.md numbers.json
numbers.json keys: ca_r ca_l ct_r ct_l (capsule mm3), pre para_r para_l (fat mm3), fossa (lumen cm3 each), lining (mm3 each),
saccule (mm3 carved), tendon, tongue, muc (hypopharyngeal mucosa mm3), con_r con_l, oes, vent (ventricle lining mm3)"""
import sys, json, re
src, dst, nums = sys.argv[1:4]; N = json.load(open(nums)); s = open(src).read()
def rep(old, new):
    global s
    assert old in s, old[:60]; s = s.replace(old, new)
rep("the framework, ligament and mucosa tables 2026-10-20 for version 5 (widening and stage 3). Status key:",
    "the framework, ligament and mucosa tables 2026-10-20 for version 5 (widening and stage 3), and the joints, ligaments, mucosa, spaces and neighbours 2026-10-20 for version 6 (stages 3b and 3c). Status key:")
rep("- **v5**: added in version 5 (stage 3) as constructed anatomy, or changed by the version-5 widening.\n",
    "- **v5**: added in version 5 (stage 3) as constructed anatomy, or changed by the version-5 widening.\n- **v6**: added in version 6 (stages 3b and 3c: spaces, fossae, hypopharynx) as constructed anatomy, or changed by the version-6 epiglottis lift.\n")
rep("| Epiglottis with petiole and perforations | v2 | Perforations present as pits. Epiglottic tubercle added in v5, see below. |",
    "| Epiglottis with petiole and perforations | v6 (lifted) | Perforations present as pits. Whole leaf lifted 5 mm in v6 so the thyro-epiglottic ligament attaches above the vestibular ligaments; leaf 30.5 mm. Epiglottic tubercle added in v5, see below. |")
rep("| Cricothyroid joint: facets, capsule, ceratocricoid ligaments | facets v2; capsule and ligaments absent | Horn tip sits 0.3 mm from the facet. No capsule. Facets at about half lamina height after the reshape; probably high. |",
    f"| Cricothyroid joint: facets, capsule, ceratocricoid ligaments | facets v2; capsule v6; ceratocricoid ligaments absent | Horn tip sits 0.3 mm from the facet. Capsule: 0.8 mm sleeve on the joint line within 4 mm of the horn tip, {N['ct_r']:.0f}/{N['ct_l']:.0f} mm³. Facets at about half lamina height after the reshape; probably high. |")
rep("| Cricoarytenoid joint: facets, capsule, posterior cricoarytenoid ligament | facets v2; capsule and ligament absent | Base seated on the lamina. The posterior cricoarytenoid ligament (which limits the arytenoid's forward travel) is absent and matters for the adducted pose. |",
    f"| Cricoarytenoid joint: facets, capsule, posterior cricoarytenoid ligament | facets v2; capsule v6; ligament in the model (parts 35/36) | Base seated on the lamina. Capsule: 0.8 mm sleeve on the joint line within 4.5 mm of the facet pad, {N['ca_r']:.0f}/{N['ca_l']:.0f} mm³, deep to the vocalis, PCA and LCA insertions. |")
rep("| Hyo-epiglottic ligament | v2 (trimmed) | Reaches hyoid and epiglottis, but has a flat cut edge from the v1 trim. Needs resculpting as a band. |",
    "| Hyo-epiglottic ligament | v6 (rebuilt to the lifted leaf) | Band from the hyoid body to the lingual face of the lifted epiglottis (z0 + 71–76); floor of the vallecula above it. |")
rep("| Thyro-epiglottic ligament | v2 | Petiole attachment. |",
    "| Thyro-epiglottic ligament | v6 (re-seated) | Lifted with the petiole; thyroid end moved 1.5 mm forward and 0.5 mm up so it sits on the floor of the superior notch, above the vestibular ligaments (the v5 order was inverted). |")
rep("| Anterior commissure tendon (Broyles' ligament) | absent | 1–2 mm structure at the ligament insertion; relevant to teaching the commissure. |",
    f"| Anterior commissure tendon (Broyles' ligament) | v6 (constructed) | 0.5 → 0.8 mm cone from 1.5 mm inside the thyroid angle to the vocal ligaments' ends, {N['tendon']:.1f} mm³, submucosal. |")
rep("| Vestibular (ventricular) ligaments | v5 (constructed) | 1 mm cord inside the false fold from the thyroid angle to the anterolateral arytenoid; 19 mm³. Attaches to the angle above the thyro-epiglottic ligament (inverted order, framework item). |",
    "| Vestibular (ventricular) ligaments | v5 (constructed) | 1 mm cord inside the false fold from the thyroid angle to the anterolateral arytenoid; 19 mm³. Since v6 it attaches below the thyro-epiglottic ligament, the right order. |")
rep("| Cricoarytenoid and cricothyroid joint capsules | absent | See joints. |",
    "| Cricoarytenoid and cricothyroid joint capsules | v6 (constructed) | See joints. |")
rep("| Laryngeal ventricle (Morgagni) and saccule | v5 (ventricle) | A 2.9 mm tall, ~3 mm deep slot between the folds, closed laterally by a mucosal ventricle wall (new part). No saccule. |",
    f"| Laryngeal ventricle (Morgagni) and saccule | v6 (saccule; ventricle wall reworked) | Ventricle from v5. In v6 the lateral wall is a 0.8 mm mucosal lining ({N['vent']:.0f} mm³ per side) with paraglottic fat behind it, and a saccule rises 8 mm from the front of each ventricle between the false fold and the lamina, lateral of the vestibular ligament (r 1.6 → 0.9 mm, {N['saccule']:.0f} mm³ of air). |")
rep("| Vallecula, median and lateral glossoepiglottic folds, tongue base | absent (tongue in source as a 524-face blob) | |",
    f"| Vallecula, median and lateral glossoepiglottic folds, tongue base | v6 (constructed stub) | Tongue base as a flat-fronted block above the hyoid ({N['tongue']/1000:.1f} cm³) with two vallecula pockets 6 × 12 mm either side of a median glossoepiglottic fold, lateral folds at x ±9.5, floor 2.5 mm on the hyo-epiglottic ligament. A landmark, not a tongue. |")
rep("| Piriform fossae | absent | The hypopharynx is not a mesh in the source; it would be built from the inferior constrictor and the laryngeal outer wall. |",
    f"| Piriform fossae | v6 (constructed) | Open recesses lateral of the aryepiglottic fold, quadrangular membrane and arytenoid, medial of the lamina and thyrohyoid membrane, apex at the vocal-fold level, {N['fossa']:.2f} cm³ each (cadaver ~1.8, Vadgaonkar 2024); 0.8 mm lining ({N['lining']:.0f} mm³) wherever tissue backs it. 8.5–9.5 mm wide, narrower than life (14–15) because the framework lamina is 19 mm from the midline. |")
rep("| Postcricoid region and oesophageal inlet | absent (oesophagus in source from the cricoid lower border down) | |",
    f"| Postcricoid region and oesophageal inlet | v6 (constructed) | Upper oesophagus as a collapsed 20 × 9 mm muscular tube on the membranous trachea from the base cut to the cricoid's lower border, 12 × 1.4 mm slit lumen ({N['oes']/1000:.1f} cm³); the source oesophagus (FMA7131) was a 132-face blob and is not used. Postcricoid mucosa is part of the hypopharyngeal mucosa below. |")
rep("| Posterior and lateral pharyngeal walls | absent (inferior constrictor in source, 3.2 cm³ per side) | |",
    f"| Posterior and lateral pharyngeal walls | v6 (source constrictors + constructed mucosa) | Inferior constrictors from BodyParts3D warped onto the frame ({N['con_r']/1000:.1f}/{N['con_l']/1000:.1f} cm³), meeting at the median raphe, attached along the oblique-line zone and continuous with the oesophagus. The hypopharynx is collapsed in the source (constrictor on the back of the larynx), so the mucosa ({N['muc']:.0f} mm³) is a 0.8 mm layer on the cricoid lamina, arytenoid backs, PCA and folds wherever the constrictor lies within 2.5 mm, plus the constrictors' inner layer where they touch: a slit, not a lumen. |")
rep("| Pre-epiglottic space (fat) | absent (void) | Behind the thyrohyoid membrane, in front of the epiglottis. Sealed from the vestibule in v5 by the anterior vestibule wall; still a void. |",
    f"| Pre-epiglottic space (fat) | v6 (filled) | Fat filled from the enclosed void: {N['pre']/1000:.2f} mL, bounded by the epiglottis, thyrohyoid membrane and median ligament, hyo-epiglottic ligament, hyoid, thyroid, quadrangular membranes, false-fold tops and the tongue block. Yellow (slot 7) in the 7-colour files. |")
rep("| Paraglottic space (fat) | partly filled (v5) | Above the folds it is filled by the false fold and the ventricle wall out to the lamina; below the fold level it is still a void (0.3–0.6 mm slits lateral of the TA). |",
    f"| Paraglottic space (fat) | v6 (filled) | {N['para_r']/1000:.2f}/{N['para_l']/1000:.2f} mL per side: the lateral wing beside the quadrangular membrane and fossa, the 1–2.5 mm pocket between the ventricle lining and the lamina, and the slit lateral of the conus below the fold. Total fat {(N['pre']+N['para_r']+N['para_l'])/1000:.2f} mL (Hermans 1997: 4.5 ± 1.0 mL for both spaces, men). |")
rep("Thyrohyoid, sternothyroid, sternohyoid, omohyoid, stylohyoid and stylohyoid ligament, digastric, mylohyoid, geniohyoid, inferior pharyngeal constrictor (thyropharyngeus + cricopharyngeus as one mesh), palatopharyngeus, stylopharyngeus.",
    "Thyrohyoid, sternothyroid, sternohyoid, omohyoid, stylohyoid and stylohyoid ligament, digastric, mylohyoid, geniohyoid, palatopharyngeus, stylopharyngeus. The inferior pharyngeal constrictor (thyropharyngeus + cricopharyngeus as one mesh) is in the model from v6; its upper border reaches 8.6 mm above the hyoid, high for the inferior constrictor alone, acceptable until a middle constrictor exists.")
rep("- Stage 3 (folds and supraglottis): done in version 5 except the vallecula, piriform fossae and pharyngeal wall, which are outside the larynx proper.",
    "- Stage 3 (folds and supraglottis): done in version 5; the spaces, saccules, capsules and tendon (3b) and the vallecula, piriform fossae and hypopharynx (3c) in version 6, which is the point where the model becomes a solid block that has to be printed in halves to be seen inside.")
open(dst, 'w').write(s); print('wrote', dst)
